SKIP = ('启动并检测', '删除模型', '选择文件', '开始资产图片制作', 'Midjourney（手动）', '云模型设置', '阶段配置', '生成记录')   # 会联网、开外部程序、弹模态框或真开工
ENGINES = (('comfy', None), ('workflow', ['CHAR_001']), ('skill', None))


class AssetBatchWindowEquivalence(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        try:
            import tkinter
            tkinter.Tk().destroy()
            cls.tk = tkinter
        except Exception:
            cls.tk = None

    def setUp(self):
        if self.tk is None:
            self.skipTest(PLATFORM_TKINTER)

    def _session(self, fn, engine, ids):
        td = Path(tempfile.gettempdir()) / ('drama_asset_batch_diff_%d' % os.getpid())
        shutil.rmtree(td, ignore_errors=True)
        td.mkdir(parents=True)
        try:
            win, desktop = _open_app(self.tk, td)
            roots = sorted({str(td), td.as_posix(), str(td.resolve()), td.resolve().as_posix()}, key=len, reverse=True)
            log = []
            try:
                desktop.cancel_timers()
                # 宿主的后台入口只记账：按钮点下去不能真的跑生产任务。
                with mock.patch.object(desktop, 'async_', lambda work, done=None, **k: log.append(('async', sorted(k)))):
                    before = set(desktop.win.winfo_children())
                    fn(desktop, engine, selected_ids=ids)
                    pump(win, 0.2)
                    popup = [w for w in desktop.win.winfo_children()
                             if w not in before and isinstance(w, self.tk.Toplevel)][-1]
                    steps = drive(popup, roots, log, skip=SKIP)
                    if popup.winfo_exists():
                        popup.destroy()
            finally:
                desktop.cancel_timers()
                win.destroy()
            return steps
        finally:
            shutil.rmtree(td, ignore_errors=True)

    def test_matches_legacy(self):
        old = legacy(module, LEGACY, 'show')
        self._session(old, 'comfy', None)   # 预热：进程里第一次建窗的布局与之后不同
        for engine, ids in ENGINES:
            with self.subTest(engine=engine):
                expected = self._session(old, engine, ids)
                actual = self._session(module.show, engine, ids)
                self.assertEqual(len(actual), len(expected))
                for a, b in zip(actual, expected):
                    self.assertEqual(a, b, a[0])
                self.assertGreater(len(expected), 3)   # 对照不能是空对空：真的点到了按钮


if __name__ == '__main__':
    unittest.main()
